package br.com.minhadieta.app;import android.content.*;import android.app.*;import androidx.core.app.NotificationCompat;
public class MealReceiver extends BroadcastReceiver{public void onReceive(Context c,Intent i){String n=i.getStringExtra("name");int id=i.getIntExtra("id",1);Intent open=new Intent(c,MainActivity.class);PendingIntent p=PendingIntent.getActivity(c,id,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);NotificationCompat.Builder b=new NotificationCompat.Builder(c,"meals").setSmallIcon(br.com.minhadieta.app.R.drawable.ic_launcher).setContentTitle("Hora de comer 🍽️").setContentText(n+" — veja o que está no seu plano.").setPriority(NotificationCompat.PRIORITY_HIGH).setAutoCancel(true).setContentIntent(p);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify(id,b.build());}}
